  String _resilienceStatusLabel() =>
      'connect ${effectiveProviderConnectTimeout.inMilliseconds}ms, '
      'idle ${effectiveProviderStreamIdleTimeout.inMilliseconds}ms, '
      'retries ×${_effectiveRetryPolicy.retriesPerEntry}';

