    return '';
  }
  final section = StringBuffer('agent:\n');
  if (contextWindowCap != null) {
    section.write('  contextWindowCap: $contextWindowCap\n');
  }
  if (agentLoadMode != null) {
    section.write('  mode: $agentLoadMode\n');
  }
  if (!misuseBreaker) {
