  buffer.write(_compactionYaml());
  if (wireDump) buffer.write('trajectory:\n  wireDump: true\n');
  if (images != null) buffer.write(_imagesYaml());
  buffer.write(_spillsYaml());
  buffer.write(_agentSectionYaml());
