    final found = _findKeyLine(lines, segments, depth, cursor);
    if (found < 0) {
      return _insertChain(
        lines,
        segments,
        depth,
        cursor,
        leafLines,
        hadTrailingNewline,
      );
    }
    if (depth == segments.length - 1) {
      return _replaceLeaf(
        lines,
        segments[depth],
        depth,
        found,
        leafLines,
        hadTrailingNewline,
