    /// flow's own writes go through [env] (the seam the flows use); the
    /// boot snapshot and every save go through the real file
    /// (`loadCliConfig`/`saveCliConfig`), exactly the two views
    /// bin/fah_runapp.dart holds.
    AgentCli bootCli() {
      final io = FakeCliIO();
