    } on Object catch (error) {
      io.writeln('not saved: $error');
      return false;
    }
    if (await _env.writeFile(path, edited) is Err) {
      io.writeln('could not write $path');
      return false;
    }
    // A user-file write just bypassed the host's whole-file save — fire
    // the re-sync hook so the next persist renders this write instead of
    // the stale boot snapshot (gh-1572 rework). Project writes touch a
    // different file; the snapshot tracks the user one only.
    if (!projectScope) await _notifyUserConfigFileChanged();
    io.writeln(
      '${segments.join('.')} = $value → $path '
      '(${note ?? applicationNote(segments.first)})',
    );
    return true;
  }

  /// Re-fetches the DAP/1 hub snapshot through the host's seam — file
  /// reads plus the hub plugin's local status snapshot, never a network
  /// dial. A missing seam leaves the null (nothing fetched); a failing one
  /// keeps the last good snapshot rather than blanking the UI.
  Future<void> _refreshDapHubSnapshot() async {
    final fetch = config.dapHubState;
    final edited = _dropTopLevelBlock(source, 'auto_update');
    // Never persist a file the next boot would reject.
    try {
      loadYaml(edited);
    } on Object catch (error) {
      io.writeln('not saved: $error');
      return false;
    }
    if (await _env.writeFile(path, edited) is Err) {
      io.writeln('could not write $path');
      return false;
    }
    await _notifyUserConfigFileChanged();
    io.writeln('auto_update removed → $path (notify is the default)');
    return true;
  }
}

